// @FIGURE_CODE_BEGIN
(function () {
  var W = 1200, H = 340;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

  var COL_BLUE = '#1f4fd8', COL_GREEN = '#2ecc2e', COL_RED = '#e01010', COL_AXIS = '#111';

  // Underlying smooth signal whose samples feed the reconstruction
  function f(t) {
    return 1.3 * Math.exp(-Math.pow(t - 1.5, 2) / 1.8)
         - 0.7 * Math.exp(-Math.pow(t - 4.2, 2) / 1.0)
         + 0.8 * Math.exp(-Math.pow(t - 6.5, 2) / 0.9);
  }
  function sinc(u) { return Math.abs(u) < 1e-9 ? 1 : Math.sin(Math.PI * u) / (Math.PI * u); }

  var N_MIN = -2, N_MAX = 7;
  var state = { Ts: 1, showComp: true, sweepLimit: N_MAX - N_MIN + 1, sweeping: false };

  var gAxis = draw.group(), gComp = draw.group(), gRed = draw.group(),
      gStem = draw.group(), gLab = draw.group(), gSym = draw.group();

  function panelX(px0, px1, tmin, tmax) {
    return function (t) { return px0 + (t - tmin) / (tmax - tmin) * (px1 - px0); };
  }

  function arrowHead(g, x, y, dir, color, sz) {
    sz = sz || 6;
    var d = dir > 0 ? -1 : 1; // tip points up for dir>0
    g.polygon((x) + ',' + (y) + ' ' + (x - sz * 0.6) + ',' + (y + d * sz) + ' ' + (x + sz * 0.6) + ',' + (y + d * sz))
      .fill(color).stroke('none');
  }

  function stem(g, x, baseY, val, scale) {
    var tipY = baseY - val * scale;
    g.line(x, baseY, x, tipY).stroke({ color: COL_BLUE, width: 2.4, linecap: 'round' });
    arrowHead(g, x, tipY, val >= 0 ? 1 : -1, COL_BLUE, 6);
    return tipY;
  }

  function samplePolyline(g, fn, X, Y, tmin, tmax, n, stroke, width, dashed, op) {
    var pts = [];
    for (var i = 0; i < n; i++) {
      var t = tmin + (tmax - tmin) * i / (n - 1);
      var v = fn(t);
      if (isFinite(v)) pts.push(X(t).toFixed(2) + ',' + Y(v).toFixed(2));
    }
    if (pts.length < 2) return null;
    var pl = g.polyline(pts.join(' ')).fill('none')
      .stroke({ color: stroke, width: width, linecap: 'round', linejoin: 'round' });
    if (dashed) pl.attr('stroke-dasharray', '6,5');
    if (op != null) pl.opacity(op);
    return pl;
  }

  function axisH(g, x0, x1, y) {
    g.line(x0, y, x1, y).stroke({ color: COL_AXIS, width: 2 });
    g.polygon(x1 + ',' + y + ' ' + (x1 - 11) + ',' + (y - 6) + ' ' + (x1 - 11) + ',' + (y + 6)).fill(COL_AXIS);
  }

  function draw() {
    gAxis.clear(); gComp.clear(); gRed.clear(); gStem.clear(); gLab.clear(); gSym.clear();
    var Ts = state.Ts;
    var baseY = 250, stemScale = 55;

    // ---- sample values ----
    var idx = [], vals = [];
    for (var n = N_MIN; n <= N_MAX; n++) { idx.push(n); vals.push(f(n * Ts)); }

    // ---- LEFT panel ----
    var tminL = N_MIN * Ts - 0.8, tmaxL = N_MAX * Ts + 0.8;
    var XL = panelX(40, 350, tminL, tmaxL);
    axisH(gAxis, 30, 360, baseY);
    gLab.text('t').font({ size: 22, style: 'italic', family: 'Georgia' }).attr({ x: 352, y: baseY + 6 }).fill(COL_AXIS);
    // ticks -Ts,0,Ts,2Ts
    [[-1, '-Tₛ'], [0, '0'], [1, 'Tₛ'], [2, '2Tₛ']].forEach(function (tk) {
      var tx = XL(tk[0] * Ts);
      gAxis.line(tx, baseY - 4, tx, baseY + 4).stroke({ color: COL_AXIS, width: 1.4 });
      gLab.text(tk[1]).font({ size: 15, family: 'Georgia', style: 'italic' }).attr({ x: tx, y: baseY + 22, 'text-anchor': 'middle' }).fill(COL_AXIS);
    });
    for (var i = 0; i < idx.length; i++) {
      var sx = XL(idx[i] * Ts);
      var tip = stem(gStem, sx, baseY, vals[i], stemScale);
      (function (sx, tip, v, nn) {
        gStem.circle(14).center(sx, tip).fill('transparent').css('cursor', 'pointer')
          .on('mousemove', function (e) { showTooltip('sample x[' + nn + '] = ' + v.toFixed(3), e); })
          .on('mouseleave', hideTooltip);
      })(sx, tip, vals[i], idx[i]);
    }

    // ---- convolution symbol ----
    gSym.circle(16).center(392, baseY).fill('none').stroke({ color: COL_AXIS, width: 2.2 });

    // ---- MIDDLE panel : sinc kernel ----
    var tminM = -4.5, tmaxM = 4.5;
    var XM = panelX(430, 750, tminM, tmaxM);
    var peakScale = 120;
    axisH(gAxis, 420, 760, baseY);
    var cx = XM(0);
    gAxis.line(cx, baseY + 10, cx, baseY - 150).stroke({ color: COL_AXIS, width: 2 });
    gAxis.polygon(cx + ',' + (baseY - 158) + ' ' + (cx - 6) + ',' + (baseY - 147) + ' ' + (cx + 6) + ',' + (baseY - 147)).fill(COL_AXIS);
    gLab.text('t').font({ size: 22, style: 'italic', family: 'Georgia' }).attr({ x: 752, y: baseY + 6 }).fill(COL_AXIS);
    gLab.text('1').font({ size: 18, family: 'Georgia' }).attr({ x: cx - 16, y: baseY - peakScale + 4 }).fill(COL_AXIS);
    samplePolyline(gComp, function (t) { return sinc(t / Ts); }, XM, function (v) { return baseY - v * peakScale; }, tminM, tmaxM, 400, COL_GREEN, 3, false, 1);

    // ---- equals sign ----
    gSym.line(782, baseY - 6, 806, baseY - 6).stroke({ color: COL_AXIS, width: 2.4 });
    gSym.line(782, baseY + 6, 806, baseY + 6).stroke({ color: COL_AXIS, width: 2.4 });

    // ---- RIGHT panel : reconstruction ----
    var XR = panelX(830, 1170, tminL, tmaxL);
    var YR = function (v) { return baseY - v * stemScale; };
    axisH(gAxis, 820, 1180, baseY);
    gLab.text('t').font({ size: 22, style: 'italic', family: 'Georgia' }).attr({ x: 1172, y: baseY + 6 }).fill(COL_AXIS);

    var lim = Math.min(state.sweepLimit, idx.length);

    // dashed green components
    if (state.showComp || state.sweeping) {
      for (var k = 0; k < lim; k++) {
        (function (k) {
          var nn = idx[k], vv = vals[k];
          samplePolyline(gComp, function (t) { return vv * sinc((t - nn * Ts) / Ts); },
            XR, YR, tminL, tmaxL, 220, COL_GREEN, 1.5, true, 0.85);
        })(k);
      }
    }

    // red reconstruction = running sum of included components
    samplePolyline(gRed, function (t) {
      var s = 0;
      for (var k = 0; k < lim; k++) s += vals[k] * sinc((t - idx[k] * Ts) / Ts);
      return s;
    }, XR, YR, tminL, tmaxL, 500, COL_RED, 3, false, 1);

    // blue stems on top (right panel)
    for (var j = 0; j < idx.length; j++) {
      stem(gStem, XR(idx[j] * Ts), baseY, vals[j], stemScale);
    }
  }

  // ---- interactions ----
  window.update_samplingInterval = function (v) { state.Ts = v; draw(); };
  window.toggle_showComponents = function (on) { state.showComp = on; draw(); };

  var sweepTimer = null;
  window.trigger_convolutionSweep = function () {
    if (sweepTimer) { clearInterval(sweepTimer); sweepTimer = null; }
    state.sweeping = true; state.sweepLimit = 0;
    document.getElementById('showComponentsInput').checked = true; state.showComp = true;
    draw();
    sweepTimer = setInterval(function () {
      state.sweepLimit++;
      draw();
      if (state.sweepLimit >= (N_MAX - N_MIN + 1)) {
        clearInterval(sweepTimer); sweepTimer = null; state.sweeping = false;
      }
    }, 320);
  };

  // ---- demo step player ----
  var steps = [
    { title: 'Superposition of sincs',
      narration: 'With components shown, every blue sample spawns its own dashed green sinc scaled to the sample’s height, and the solid red curve is their sum — which is why it passes exactly through each sample tip.',
      state: { samplingInterval: 1, showComponents: true } },
    { title: 'The sum alone',
      narration: 'Hiding the individual sincs leaves only the red reconstructed signal threading the samples, making clear that the dashed curves are just the hidden ingredients of that single continuous result.',
      state: { samplingInterval: 1, showComponents: false } },
    { title: 'Push past Nyquist',
      narration: 'Drag Tₛ upward: samples spread apart, the green sinc copies begin to overlap heavily, and the red envelope no longer matches the original signal — this is aliasing from under-sampling.',
      state: { samplingInterval: 1.8, showComponents: true } },
    { title: 'Build it sample by sample',
      narration: 'Run the convolution sweep to watch the sinc filter step across each sample position, adding one scaled sinc at a time and growing the red envelope from left to right until it equals the full reconstruction.',
      state: { samplingInterval: 1, showComponents: true, sweep: true } }
  ];
  var cur = -1;
  function applyStep(i) {
    cur = i;
    var s = steps[i];
    document.getElementById('samplingIntervalInput').value = s.state.samplingInterval;
    document.getElementById('samplingIntervalVal').value = s.state.samplingInterval;
    update_samplingInterval(s.state.samplingInterval);
    document.getElementById('showComponentsInput').checked = s.state.showComponents;
    toggle_showComponents(s.state.showComponents);
