    var s = steps[i];
    document.getElementById('samplingIntervalInput').value = s.state.samplingInterval;
    document.getElementById('samplingIntervalVal').value = s.state.samplingInterval;
    update_samplingInterval(s.state.samplingInterval);
    document.getElementById('showComponentsInput').checked = s.state.showComponents;
    toggle_showComponents(s.state.showComponents);
    if (s.state.sweep) trigger_convolutionSweep();
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = (i + 1) + '/' + steps.length + ' · ' + s.title;
  }
  window.nextStep = function () { applyStep(Math.min(cur + 1, steps.length - 1)); };
  window.prevStep = function () { applyStep(Math.max(cur - 1, 0)); };

  document.addEventListener('fig-resize', function () { /* viewBox scales automatically */ });

  draw();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Ideal reconstruction of a continuous signal from its samples is a linear superposition of shifted, sample-scaled sinc kernels, and sampling too coarsely (T_s above the Nyquist limit) makes those sincs overlap and alias, distorting the reconstructed envelope.
KEY INSIGHT (what students should walk away understanding): Reconstruction is nothing more than adding up one shifted, sample-scaled sinc per sample — and the whole process only works while the sampling rate keeps those sincs from overlapping into aliasing.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Ideal reconstruction of a continuous signal from its samples is a linear superposition of shifted, sample-scaled sinc kernels, and sampling too coarsely (T_s above the Nyquist limit) makes those sincs overlap and alias, distorting the reconstructed envelope.",
  "figureType": "diagram",
  "elements": [
    "left panel: horizontal time axis t with arrowhead",
    "left panel: blue vertical impulse arrows (stems) at sample positions, mixed positive and negative heights",
    "left panel: axis tick labels -T_s, 0, T_s, 2T_s",
    "convolution operator symbol (small open circle) between left and middle panels",
    "middle panel: horizontal time axis t and vertical axis with arrowhead",
    "middle panel: green sinc-like reconstruction kernel centered at 0 with peak value labeled 1 and decaying oscillating sidelobes",
    "equals sign between middle and right panels",
    "right panel: horizontal time axis t with arrowhead",
    "right panel: blue impulse arrows at the same sample positions as the left panel",
    "right panel: dashed green scaled-and-shifted sinc copies, one centered at each sample and scaled by that sample's height",
    "right panel: solid red reconstructed continuous curve passing exactly through the tip of every blue sample arrow"
  ],
  "interactions": [
    {
      "id": "samplingInterval",
      "type": "slider",
      "label": "Sampling interval T_s",
      "range": [
        0.5,
        2,
        0.1
      ],
      "default": 1,
      "teaches": "Decreasing T_s packs samples densely so the green sinc copies stay well separated and the red envelope cleanly tracks the underlying signal; increasing T_s past the Nyquist limit forces the sinc copies to overlap and the red envelope to alias away from the true signal"
    },
    {
      "id": "showComponents",
      "type": "toggle",
      "label": "Show individual sinc components",
      "default": true,
      "teaches": "Each blue sample contributes exactly one shifted, height-scaled sinc (a dashed green curve); the solid red reconstruction is simply the pointwise sum of all those components, so the red curve is forced to pass through every sample tip"
    },
    {
      "id": "convolutionSweep",
      "type": "animation",
      "label": "Convolution sweep",
      "loop": false,
      "teaches": "Sweeping the sinc filter across the sample positions one by one and accumulating the result shows the red envelope being built up incrementally from left to right as each sample's sinc is added to the running sum"
    }
  ],
  "demo_steps": [
    {
      "title": "Superposition of sincs",
      "narration": "With components shown, every blue sample spawns its own dashed green sinc scaled to the sample's height, and the solid red curve is their sum — which is why it passes exactly through each sample tip.",
      "state": {
        "samplingInterval": 1,
        "showComponents": true
      }
    },
    {
      "title": "The sum alone",
      "narration": "Hiding the individual sincs leaves only the red reconstructed signal threading the samples, making clear that the dashed curves are just the hidden ingredients of that single continuous result.",
      "state": {
        "samplingInterval": 1,
        "showComponents": false
      }
    },
    {
      "title": "Push past Nyquist",
      "narration": "Drag T_s upward: samples spread apart, the green sinc copies begin to overlap heavily, and the red envelope no longer matches the original signal — this is aliasing from under-sampling.",
      "state": {
        "samplingInterval": 1.8,
        "showComponents": true
      }
    },
    {
      "title": "Build it sample by sample",
      "narration": "Run the convolution sweep to watch the sinc filter step across each sample position, adding one scaled sinc at a time and growing the red envelope from left to right until it equals the full reconstruction.",
      "state": {
        "samplingInterval": 1,
        "showComponents": true
      }
    }
  ],
  "keyInsight": "Reconstruction is nothing more than adding up one shifted, sample-scaled sinc per sample — and the whole process only works while the sampling rate keeps those sincs from overlapping into aliasing.",
  "reconstructionNotes": "Lay out three panels left-to-right joined by a small open-circle convolution symbol and an equals sign, exactly like a visual equation. Left panel: a black horizontal t-axis with blue stem arrows of varying positive/negative heights at evenly spaced ticks labeled -T_s, 0, T_s, 2T_s. Middle panel: a bright green sinc curve peaked at 1 (label the peak '1') with a vertical axis and decaying oscillating sidelobes. Right panel: same blue stems as the left, overlaid with dashed green sinc copies centered and scaled at each stem, and a bold solid red curve that interpolates through every stem tip. Keep blue for samples, green for kernel/components, red for the reconstruction throughout so the color coding itself teaches the superposition. When T_s grows, re-space the stems and widen the sincs so the dashed copies visibly overlap and the red curve develops aliasing ripples; the convolution sweep should reveal dashed sincs sequentially and accumulate the red curve left-to-right."
}

